if __name__ == "__main__":
    out = Path(__file__).with_name("golden.tsv")
    with open(out, "w", encoding="utf-8") as f:
        f.write("id\tyaml\tprobe\toptions\texpected\n")
        for i, (y, p, o, e) in enumerate(R, 1):
            f.write(f"g{i:03d}\t{json.dumps(y)}\t{p}\t{o}\t{e}\n")
    print(len(R), "golden rows")
